<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { activeWorkshops, findDuplicates, listCustomers, setCustomerStatus, updateCustomer } from '../services/customers'
import type { Customer, CustomerPayload, Workshop } from '../types'
import { useRouter } from 'vue-router'
import SmartAddressFields from '../components/SmartAddressFields.vue'
const router = useRouter(); const workshops = ref<Workshop[]>([]); const customers = ref<Customer[]>([]); const loading = ref(false); const search = ref(''); const status = ref('todos'); const workshopId = ref<number | null>(null); const edit = ref<Customer | null>(null); const confirmDisable = ref<Customer | null>(null); const message = ref(''); const successNotice = ref(''); const error = ref(''); const editSaving = ref(false); const originalEditPayload = ref<CustomerPayload | null>(null)
const editForm = ref<CustomerPayload>({ first_name:'', paternal_surname:'', maternal_surname:'', street_and_number:'', neighborhood:'', postal_code:'', municipality:'', state:'', primary_email:'', secondary_email:'', primary_phone:'', secondary_phone:'' })
const headers = [{ title:'Cliente',key:'name'},{title:'Contacto',key:'contact'},{title:'Taller',key:'workshop_name'},{title:'Estado',key:'is_active'},{title:'Registro',key:'created_at'},{title:'Acciones',key:'actions',sortable:false}]
const activeCount = computed(() => customers.value.filter(x=>x.is_active).length); const inactiveCount = computed(() => customers.value.length-activeCount.value)
async function load(){ loading.value=true; error.value=''; try{customers.value=await listCustomers({workshop_id:workshopId.value||undefined,search:search.value,status_filter:status.value})}catch(c:any){error.value=c.response?.data?.detail||'No fue posible cargar clientes.'}finally{loading.value=false}}
function normalizedEditPayload(source: CustomerPayload): CustomerPayload { return { first_name: source.first_name.trim(), paternal_surname: source.paternal_surname.trim(), maternal_surname: source.maternal_surname?.trim() || null, street_and_number: source.street_and_number.trim(), neighborhood: source.neighborhood.trim(), postal_code: source.postal_code.trim(), municipality: source.municipality.trim(), state: source.state.trim(), primary_email: source.primary_email.trim().toLowerCase(), secondary_email: source.secondary_email?.trim().toLowerCase() || null, primary_phone: source.primary_phone.replace(/\D/g, ''), secondary_phone: source.secondary_phone?.replace(/\D/g, '') || null } }
function editValidationError(payload: CustomerPayload) { if(payload.first_name.length<2)return 'El nombre debe tener al menos 2 caracteres.'; if(payload.paternal_surname.length<2)return 'El apellido paterno debe tener al menos 2 caracteres.'; if(payload.street_and_number.length<4)return 'La calle y número debe tener al menos 4 caracteres.'; if(!payload.state || !payload.municipality || !payload.neighborhood)return 'Completa el estado, municipio y colonia o localidad.'; if(!/^\d{5}$/.test(payload.postal_code))return 'El código postal debe tener cinco dígitos.'; if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(payload.primary_email))return 'Escribe un correo electrónico principal válido.'; if(payload.secondary_email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(payload.secondary_email))return 'Escribe un correo electrónico secundario válido.'; if(!/^\d{10}$/.test(payload.primary_phone))return 'El teléfono principal debe tener 10 dígitos.'; if(payload.secondary_phone && !/^\d{10}$/.test(payload.secondary_phone))return 'El teléfono secundario debe tener 10 dígitos.'; return '' }
function apiErrorMessage(c: any) { const detail = c?.response?.data?.detail; if(Array.isArray(detail)) return detail.map((entry:any)=>entry.msg || entry.message).filter(Boolean).join(' ') || 'Los datos no se guardaron correctamente'; return typeof detail === 'string' && detail ? detail : 'Los datos no se guardaron correctamente' }
function beginEdit(item:Customer){ edit.value=item; editForm.value={first_name:item.first_name,paternal_surname:item.paternal_surname,maternal_surname:item.maternal_surname||'',street_and_number:item.street_and_number,neighborhood:item.neighborhood||'',postal_code:item.postal_code||'',municipality:item.municipality,state:item.state,primary_email:item.primary_email,secondary_email:item.secondary_email||'',primary_phone:item.primary_phone,secondary_phone:item.secondary_phone||''}; originalEditPayload.value=normalizedEditPayload(editForm.value) }
async function saveEdit(){ if(!edit.value)return; const payload=normalizedEditPayload(editForm.value); if(JSON.stringify(payload)===JSON.stringify(originalEditPayload.value))return; const validationError=editValidationError(payload); if(validationError){error.value=validationError;return}; editSaving.value=true; try { const duplicates=await findDuplicates(edit.value.workshop_id,payload,edit.value.id); if(duplicates.contact_in_use || duplicates.exact.length){error.value='El correo electrónico o teléfono ya está registrado. Verifica los datos para continuar.';return}; await updateCustomer(edit.value.id,edit.value.workshop_id,payload); edit.value=null; originalEditPayload.value=null; await load(); successNotice.value='Los datos del cliente se guardaron correctamente.' }catch(c:any){error.value=apiErrorMessage(c)}finally{editSaving.value=false} }
async function disable(){if(!confirmDisable.value)return;try{await setCustomerStatus(confirmDisable.value.id,confirmDisable.value.workshop_id,false);message.value='Cliente desactivado sin eliminar su historial.';confirmDisable.value=null;await load()}catch(c:any){error.value=c.response?.data?.detail||'No fue posible desactivar.'}}
function vehicle(item:Customer){router.push({path:'/vehiculos/registro',query:{customer_id:String(item.id),workshop_id:String(item.workshop_id)}})}
watch([search,status,workshopId],load); watch(error,value=>{if(value)setTimeout(()=>{if(error.value===value)error.value=''},3000)}); watch(successNotice,value=>{if(value)setTimeout(()=>{if(successNotice.value===value)successNotice.value=''},3000)}); onMounted(async()=>{try{workshops.value=await activeWorkshops()}catch{error.value='No fue posible cargar talleres.'};await load()})
</script>
<template>
  <v-container class="page-shell customers-admin">
    <header class="page-header"><p class="eyebrow">GESTIÓN DE CLIENTES</p><div class="header-row"><div class="header-icon"><v-icon icon="mdi-account-group-outline" size="27"/></div><div><h1>Administración de clientes</h1><p class="subtitle">Consulta, actualiza y conserva el historial operativo de tus clientes.</p></div></div></header>
    <v-alert v-if="successNotice" class="customer-admin-success mb-5" variant="flat"><v-icon icon="mdi-check-circle" class="mr-2" />{{successNotice}}</v-alert>
    <v-alert v-if="error" type="error" closable variant="tonal" class="mb-5" @click:close="error=''">{{error}}</v-alert>
    <section class="metrics"><v-card class="metric" elevation="0"><div class="metric-icon blue"><v-icon icon="mdi-account-group-outline"/></div><strong>{{customers.length}}</strong><span>Clientes registrados</span></v-card><v-card class="metric" elevation="0"><div class="metric-icon green"><v-icon icon="mdi-check-circle-outline"/></div><strong>{{activeCount}}</strong><span>Clientes activos</span></v-card><v-card class="metric" elevation="0"><div class="metric-icon amber"><v-icon icon="mdi-account-off-outline"/></div><strong>{{inactiveCount}}</strong><span>Clientes inactivos</span></v-card></section>
    <v-card class="module-card" elevation="0"><div class="table-heading"><div><h2>Directorio de clientes</h2><p>Filtra los registros por estado, taller o datos de contacto.</p></div></div><v-divider/><v-card-text class="pb-2"><v-row class="align-center"><v-col cols="12" md="5"><v-text-field v-model="search" prepend-inner-icon="mdi-magnify" label="Buscar por nombre, correo o teléfono" variant="outlined" density="comfortable" hide-details clearable/></v-col><v-col cols="12" sm="6" md="3"><v-select v-model="status" label="Estado" :items="[{title:'Todos los estados',value:'todos'},{title:'Activos',value:'activos'},{title:'Inactivos',value:'inactivos'}]" variant="outlined" density="comfortable" hide-details/></v-col><v-col cols="12" sm="6" md="4"><v-select v-model="workshopId" clearable label="Centro automotriz" :items="workshops" item-title="name" item-value="id" variant="outlined" density="comfortable" hide-details/></v-col></v-row></v-card-text>
      <v-data-table class="customer-table" :headers="headers" :items="customers" :loading="loading" hover><template #item.name="{item}"><div class="customer-name"><v-avatar color="primary" variant="tonal" size="34">{{item.first_name.slice(0,1)}}{{item.paternal_surname.slice(0,1)}}</v-avatar><div><strong>{{item.first_name}} {{item.paternal_surname}} {{item.maternal_surname}}</strong><small>{{item.state}}, {{item.municipality}}</small></div></div></template><template #item.contact="{item}"><div class="contact-cell"><span>{{item.primary_email}}</span><small>{{item.primary_phone}}</small></div></template><template #item.is_active="{item}"><v-chip :color="item.is_active?'success':'grey'" size="small" variant="tonal" class="status-chip"><v-icon start size="13" :icon="item.is_active?'mdi-check-circle':'mdi-pause-circle'"/>{{item.is_active?'Activo':'Inactivo'}}</v-chip></template><template #item.created_at="{item}">{{new Date(item.created_at).toLocaleDateString('es-MX')}}</template><template #item.actions="{item}"><div class="actions"><v-tooltip text="Editar"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-pencil-outline" size="small" variant="tonal" color="primary" :disabled="!item.is_active" @click="beginEdit(item)"/></template></v-tooltip><v-tooltip text="Asociar vehículo"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-car-plus" size="small" variant="tonal" color="primary" :disabled="!item.is_active" @click="vehicle(item)"/></template></v-tooltip><v-tooltip text="Desactivar"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-account-off-outline" size="small" variant="tonal" color="error" :disabled="!item.is_active" @click="confirmDisable=item"/></template></v-tooltip></div></template></v-data-table>
    </v-card>
    <v-dialog :model-value="!!edit" max-width="880" scrollable persistent><v-card v-if="edit" class="dialog-card customer-edit-dialog"><header class="customer-edit-dialog__header"><div class="customer-edit-dialog__header-icon"><v-icon icon="mdi-account-edit-outline" size="25"/></div><div><h2>Actualizar cliente</h2><p>Modifica los datos permitidos del registro seleccionado.</p></div></header><v-card-text class="customer-edit-dialog__content"><section class="customer-edit-workshop"><v-icon icon="mdi-storefront-outline" size="20"/><div><span>Centro automotriz asociado</span><strong>{{edit.workshop_name}}</strong></div><small>Asociación no modificable</small></section><section class="customer-edit-section"><div class="customer-edit-section__title"><span><v-icon icon="mdi-account-outline"/></span><div><h3>Datos personales</h3><p>Información de identificación del cliente.</p></div></div><v-row><v-col cols="12" md="4"><v-text-field v-model="editForm.first_name" label="Nombre *" prepend-inner-icon="mdi-account-outline" variant="outlined" density="comfortable"/></v-col><v-col cols="12" md="4"><v-text-field v-model="editForm.paternal_surname" label="Apellido paterno *" prepend-inner-icon="mdi-account-outline" variant="outlined" density="comfortable"/></v-col><v-col cols="12" md="4"><v-text-field v-model="editForm.maternal_surname" label="Apellido materno" prepend-inner-icon="mdi-account-outline" variant="outlined" density="comfortable"/></v-col></v-row></section><section class="customer-edit-section"><div class="customer-edit-section__title"><span><v-icon icon="mdi-map-marker-outline"/></span><div><h3>Domicilio</h3><p>Ubicación registrada para contacto y servicio.</p></div></div><v-row><v-col cols="12"><v-text-field v-model="editForm.street_and_number" label="Calle y número *" prepend-inner-icon="mdi-road-variant" variant="outlined" density="comfortable"/></v-col></v-row><SmartAddressFields :show-icons="true" v-model:state="editForm.state" v-model:municipality="editForm.municipality" v-model:neighborhood="editForm.neighborhood" v-model:postal-code="editForm.postal_code"/></section><section class="customer-edit-section"><div class="customer-edit-section__title"><span><v-icon icon="mdi-card-account-phone-outline"/></span><div><h3>Contacto</h3><p>Datos principales para comunicación con el cliente.</p></div></div><v-row><v-col cols="12" md="6"><v-text-field v-model="editForm.primary_email" label="Correo electrónico *" type="email" prepend-inner-icon="mdi-email-outline" variant="outlined" density="comfortable"/></v-col><v-col cols="12" md="6"><v-text-field v-model="editForm.primary_phone" label="Teléfono principal *" prepend-inner-icon="mdi-phone-outline" variant="outlined" density="comfortable"/></v-col></v-row></section></v-card-text><v-card-actions class="dialog-actions customer-edit-dialog__actions"><v-spacer/><v-btn class="customer-edit-cancel" variant="outlined" prepend-icon="mdi-close" :disabled="editSaving" @click="edit=null">Cancelar</v-btn><v-btn class="customer-edit-save" color="primary" variant="flat" prepend-icon="mdi-content-save-outline" :loading="editSaving" :disabled="editSaving" @click="saveEdit">Guardar cambios</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!confirmDisable" max-width="480" persistent><v-card v-if="confirmDisable" class="dialog-card customer-deactivate-dialog"><header class="customer-deactivate-dialog__header"><div class="customer-deactivate-dialog__header-icon"><v-icon icon="mdi-storefront-outline" size="25"/></div><div><h2>Desactivar cliente</h2><p>Confirma esta acción antes de continuar.</p></div></header><v-card-text class="customer-deactivate-dialog__content"><v-icon class="customer-deactivate-dialog__warning" icon="mdi-alert-circle-outline" size="58"/><h3>¿Seguro que deseas <span>dar de baja</span> a este cliente?</h3><strong class="customer-deactivate-dialog__name">{{confirmDisable.first_name}} {{confirmDisable.paternal_surname}} {{confirmDisable.maternal_surname}}</strong><p>El cliente dejará de estar disponible para nuevas operaciones. Su historial se conservará.</p></v-card-text><v-card-actions class="customer-deactivate-dialog__actions"><v-spacer/><v-btn class="customer-deactivate-dialog__cancel" variant="outlined" prepend-icon="mdi-close" @click="confirmDisable=null">Cancelar</v-btn><v-btn class="customer-deactivate-dialog__confirm" variant="flat" prepend-icon="mdi-account-off-outline" @click="disable">Desactivar</v-btn></v-card-actions></v-card></v-dialog><v-snackbar :model-value="!!message" color="success" @update:model-value="message=''">{{message}}</v-snackbar>
  </v-container>
</template>
<style scoped>
.page-shell{max-width:1280px;padding:38px 32px 64px}.page-header{margin-bottom:28px}.header-row,.dialog-heading{display:flex;gap:14px;align-items:flex-start}.header-icon,.metric-icon{display:grid;place-items:center;flex:none;border-radius:12px;background:#edf3ff;color:#3867de}.header-icon{width:52px;height:52px}.eyebrow{margin:0 0 8px;color:#3364a2;font-weight:800;letter-spacing:1.3px;font-size:.72rem}.page-header h1{margin:0;color:#172b4d;font-size:clamp(1.8rem,2.6vw,2.3rem);line-height:1.15;font-weight:800}.subtitle,.table-heading p,.dialog-heading p{margin:5px 0 0;color:#66758b;font-size:.88rem}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:24px}.metric,.module-card,.dialog-card{border:1px solid #e4e9f2;border-radius:16px;background:#fff;box-shadow:0 12px 28px rgba(23,43,77,.05)}.metric{min-height:142px;padding:20px;display:flex;flex-direction:column;align-items:flex-start;gap:8px}.metric-icon{width:40px;height:40px}.metric-icon.green{background:#e7f6ed;color:#25834a}.metric-icon.amber{background:#fff4df;color:#b87920}.metric strong{font-size:1.75rem;line-height:1;color:#172b4d}.metric span{color:#748197;font-size:.82rem}.table-heading{padding:24px 24px 18px}.table-heading h2,.dialog-heading h2{margin:0;color:#172b4d;font-size:1.1rem}.customer-table :deep(th){color:#718096!important;font-size:.72rem!important;font-weight:800!important;letter-spacing:.5px;background:#f6f8fc}.customer-table :deep(td){border-color:#edf1f7!important;padding-block:14px!important}.customer-name{display:flex;align-items:center;gap:10px}.customer-name strong,.contact-cell span{display:block;color:#263852;font-size:.88rem}.customer-name small,.contact-cell small{display:block;color:#718096;margin-top:3px}.actions{display:flex;gap:6px;justify-content:flex-end}.status-chip{font-weight:700}.dialog-card{overflow:hidden}.dialog-heading{padding:24px 28px 0}.dialog-actions{padding:16px 28px 22px}.dialog-actions .v-btn{text-transform:none;font-weight:700}.customer-admin-success{border:1px solid #b9dfbd!important;background:#eaf7ea!important;color:#237e18!important;font-weight:700}.customer-edit-dialog{display:flex;max-height:min(840px,calc(100dvh - 44px));flex-direction:column;overflow:hidden}.customer-edit-dialog:before,.customer-deactivate-dialog:before{display:none!important}.customer-edit-dialog__header{display:flex;align-items:center;gap:14px;flex:none;padding:22px 28px;border-bottom:1px solid #dbe6f5;background:#eef3fc}.customer-edit-dialog__header-icon{display:grid;place-items:center;width:46px;height:46px;flex:none;border-radius:13px;background:#f8e9ce;color:#2850e8}.customer-edit-dialog__header h2{margin:0;color:#142b50;font-size:1.25rem;font-weight:800}.customer-edit-dialog__header p{margin:4px 0 0;color:#64748b;font-size:.86rem}.customer-edit-dialog__content{flex:1;overflow:auto;padding:20px 28px 8px}.customer-edit-workshop{display:flex;align-items:center;gap:11px;margin-bottom:4px;padding:13px 15px;border:1px solid #dbe6f5;border-radius:13px;background:#eef3fc;color:#2850e8}.customer-edit-workshop>div{display:grid;gap:2px}.customer-edit-workshop span{color:#64748b;font-size:.74rem;font-weight:700}.customer-edit-workshop strong{color:#142b50;font-size:.9rem}.customer-edit-workshop small{margin-left:auto;color:#64748b;font-size:.72rem}.customer-edit-section{padding:20px 0 12px;border-bottom:1px solid #e3eaf3}.customer-edit-section:last-child{border-bottom:0}.customer-edit-section__title{display:flex;align-items:center;gap:11px;margin-bottom:10px}.customer-edit-section__title>span{display:grid;place-items:center;width:38px;height:38px;flex:none;border-radius:50%;background:#f8e9ce;color:#2850e8}.customer-edit-section__title h3{margin:0;color:#142b50;font-size:1.05rem;font-weight:800}.customer-edit-section__title p{margin:3px 0 0;color:#64748b;font-size:.8rem}.customer-edit-dialog__actions{flex:none;margin-top:auto;padding:16px 28px 20px;border-top:1px solid #dfe7f2;background:#f8faff}.customer-edit-cancel{min-width:112px;border-color:#cbd5e1!important;color:#536276!important}.customer-edit-cancel:hover:not(.v-btn--disabled),.customer-edit-cancel:focus-visible:not(.v-btn--disabled){border-color:#dc3545!important;background:rgba(220,53,69,.1)!important;color:#dc3545!important}.customer-edit-save{min-width:156px;background:#2850e8!important;color:#fff!important;transition:background-color .2s ease!important}.customer-edit-save:hover:not(.v-btn--disabled),.customer-edit-save:focus-visible:not(.v-btn--disabled){background:#253b60!important;color:#fff!important}.customer-edit-save :deep(.v-icon){color:#fff!important}.customer-deactivate-dialog{text-align:center}.customer-deactivate-dialog__header{display:flex;align-items:center;gap:13px;padding:22px 26px;border-bottom:1px solid #f0d9dc;background:#fffafa;text-align:left}.customer-deactivate-dialog__header-icon{display:grid;place-items:center;width:44px;height:44px;border-radius:12px;background:#fdebed;color:#2850e8}.customer-deactivate-dialog__header h2{margin:0;color:#142b50;font-size:1.14rem;font-weight:800}.customer-deactivate-dialog__header p{margin:4px 0 0;color:#64748b;font-size:.82rem}.customer-deactivate-dialog__content{padding:24px 30px 22px}.customer-deactivate-dialog__warning{display:block;margin:0 auto 13px;color:#dc3545}.customer-deactivate-dialog__content h3{margin:0;color:#142b50;font-size:1.14rem;line-height:1.4}.customer-deactivate-dialog__content h3 span{color:#dc3545}.customer-deactivate-dialog__name{display:block;margin:12px 0 8px;color:#475569;font-size:.92rem}.customer-deactivate-dialog__content p{max-width:345px;margin:0 auto;color:#64748b;font-size:.86rem;line-height:1.55}.customer-deactivate-dialog__actions{padding:16px 26px 22px;border-top:1px solid #edf0f4;background:#fff}.customer-deactivate-dialog__cancel{min-width:112px;border-color:#cbd5e1!important;background:#fff!important;color:#475569!important}.customer-deactivate-dialog__cancel:hover{border-color:#334155!important;background:#334155!important;color:#fff!important}.customer-deactivate-dialog__confirm{min-width:126px;background:linear-gradient(135deg,#dc3545,#b91c2c)!important;color:#fff!important;box-shadow:0 7px 16px rgba(185,28,44,.22)}.customer-deactivate-dialog__confirm:hover{background:linear-gradient(135deg,#b91c2c,#8f1724)!important;color:#fff!important}@media(max-width:850px){.metrics{grid-template-columns:1fr}.page-shell{padding:24px 16px 42px}}@media(max-width:600px){.table-heading{padding:20px}.actions{justify-content:flex-start}.customer-table{min-width:760px}.customer-edit-dialog__header,.customer-edit-dialog__content,.customer-edit-dialog__actions{padding-left:18px;padding-right:18px}.customer-edit-workshop{align-items:flex-start}.customer-edit-workshop small{display:none}.customer-edit-dialog__actions{gap:8px}.customer-edit-dialog__actions .v-btn{flex:1;min-width:0}.customer-deactivate-dialog__actions{gap:8px}.customer-deactivate-dialog__actions .v-btn{flex:1;min-width:0}}
